grid=[[8,8,1,1,1,1,1,1,8],[8,8,1,8,1,8,8,8,8],[8,8,8,8,1,8,8,8,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,1,8,8,1,8],[8,8,1,8,8,8,8,1,8],[8,8,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8]]
# Iteratively fill background cells lying between any pair of markers in a row or column.
R,C=len(grid),len(grid[0]); out=[r[:] for r in grid]
while True:
    add=set()
    for r in range(R):
        xs=[c for c,v in enumerate(out[r]) if v in (1,2)]
        if len(xs)>1:
            for a,b in zip(xs,xs[1:]):
                add.update((r,c) for c in range(a+1,b) if out[r][c]==8)
    for c in range(C):
        ys=[r for r in range(R) if out[r][c] in (1,2)]
        if len(ys)>1:
            for a,b in zip(ys,ys[1:]):
                add.update((r,c) for r in range(a+1,b) if out[r][c]==8)
    if not add: break
    for r,c in add: out[r][c]=2
print('added',sorted((r,c) for r in range(R) for c in range(C) if out[r][c]==2))
print(out)

